(async()=>{const file=path.join(source,'banner-source.png'),out=path.join(project,'miniprogram/assets/industry/banner-wheat-gold-v1.png');await sharp(file).resize(1050,355,{fit:'fill'}).png({palette:true,colours:192,quality:95,dither:.3,compressionLevel:9}).toFile(out);const info={approvedDirection:'2026-10-20 user selected wheat-gold ribbon and wheat ears for industry; ecology stays green mountain-water.',source:'design-source/industry-wheat-20261020/banner-source.png',prompt:'design-source/industry-wheat-20261020/prompt.txt',runtime:'miniprogram/assets/industry/banner-wheat-gold-v1.png',method:'Built-in ImageGen edit of original header; resize and palette compression only. Original green header retained unchanged.',width:1050,height:355,bytes:fs.statSync(out).size,sha256:crypto.createHash('sha256').update(fs.readFileSync(out)).digest('hex')};fs.writeFileSync(path.join(source,'asset-manifest.json'),JSON.stringify(info,null,2)+'\n');console.log(JSON.stringify(info,null,2));})().catch(e=>{console.error(e);process.exit(1)});
